const val S_ITAL = 34
const val S_COUNT = 35

fun tr(i: Int): String = Lang.get(i)

object Lang {
    private var code = "en"
    private val cache = HashMap<String, List<String>>()

    /** Nimmt die erste Sprache der Liste, die die App kennt. Sonst Englisch. */
    fun setup(list: LocaleList) {
        for (i in 0 until list.size()) {
            val c = resolve(list.get(i))
            if (DATA.containsKey(c)) {
                code = c
                return
            }
        }
        code = "en"
    }

    private fun resolve(l: Locale): String {
        val lang = when (val c = l.language) {
            "in" -> "id"
            "tl" -> "fil"
            "nb", "nn" -> "no"
            else -> c
        }
        return when (lang) {
            "zh" -> if (l.script == "Hant" || l.country == "TW" || l.country == "HK" || l.country == "MO") "zh-Hant" else "zh"
            "ar" -> when (l.country) {
                "EG" -> "arz"
                "MA" -> "ary"
                else -> "ar"
            }
            "sr" -> if (l.script == "Latn") "hr" else "sr"
            else -> lang
        }
    }

    private fun parts(c: String): List<String> =
        cache.getOrPut(c) {
            val en = DATA.getValue("en").split("|")
            val p = (DATA[c] ?: DATA.getValue("en")).split("|")
            if (p.size == S_COUNT) p else en
        }

    fun get(i: Int): String {
        val s = parts(code).getOrElse(i) { "" }
        return if (s.isBlank()) parts("en").getOrElse(i) { "" } else s
    }
}

